      {σ : State C Γ} {amount} (h : StmtDemand hs σ amount) : Demand (.cons hs hp) σ amount
  | tail {Γ Δ Ξ F G K s P head tail}
      {hs : StmtCert b (Γ := Γ) (Δ := Δ) F G s head}
